	for lineIdx, line := range lines {
		mk := regexp.MustCompile(`^\s*"([^"]+)"`).FindStringSubmatch(line)
		if len(mk) != 2 {
			kept = append(kept, line)
			continue
		}
		key := mk[1]
		prefixHit := ""
		for _, p := range prefixes {
			if strings.HasPrefix(key, p) {
				prefixHit = p
				break
			}
		}
		if prefixHit == "" {
			kept = append(kept, line)
			continue
		}
		suffix := strings.TrimPrefix(key, prefixHit)
		if shouldKeepNonAttributeSuffix(suffix) {
			kept = append(kept, line)
		} else {
			removedIdx = append(removedIdx, lineIdx)
